/** The trailing "Sources" block the backend appends to a cited answer (news_search.render_citations, Part C):
 *
 *      <text>\n\nSources\n[1] <source> · "<headline>" · <date> · <url>\n[2] FPL official notice · <date>
 *
 *  Checkpoint C7: the Chat page hides that block ONLY on an exact match of that shape (every line "[n] ...", n counting
 *  from 1) and only when the answer carries sources[]; otherwise the text is shown whole (both the text list and the
 *  chips). The fixtures in e2e/fixtures/render_citations.json are generated by the server function itself. */

const BLOCK = /\n\nSources\n((?:\[\d+\] [^\n]+(?:\n|$))+)$/;

export function stripSourcesBlock(text: string, hasSources: boolean): { text: string; stripped: boolean } {
  if (!hasSources || !text) return { text, stripped: false };
  const m = BLOCK.exec(text);
  if (!m) return { text, stripped: false };
  const lines = m[1].replace(/\n$/, "").split("\n");
  const numbered = lines.every((line, i) => line.startsWith(`[${i + 1}] `));
  if (!numbered) return { text, stripped: false };
  return { text: text.slice(0, m.index).replace(/\s+$/, ""), stripped: true };
}
